# ORIGINAL: TOP1 prompt rows (audit D-0402 item 2(b)): `PL_write_prompt` (pl-file.c:1868), `PrologPrompt` (pl-file.c:3795), `prompt1/1`'s once-only
# atom and `prompt/2`'s atom at the start of a line, against swipl 10.1.19-1-gcbf4e189 DRIVEN ON A PSEUDO-TERMINAL; the pins are generated by
# evidence/TOP1/gen_top1_rows.py.
# test/core_lang/test_top1_prompt_swipl.jl — what swipl writes before each read of `user_input`, and what the kernel's prompt functions write.
#   * swipl writes the prompt in `Sread_terminal` (pl-os.c:2171-2185) and ONLY for a terminal input (`SIO_ISATTY`), so the generator runs swipl
#     on a pty (echo off), feeds one line per step and drains the output after each line. A transcript is n+1 segments for n steps: the output
#     before the first line, then the output after each line (the goal's own text, then the next prompt).
#   * The kernel has no terminal read yet: `Sread_user` (pl-file.c:5987) and `Sread_terminal` are left to TOP1b. The harness `_tp_transcript` is
#     their three lines made by hand (`prompt.next` set at the start, as `ResetTty` does, and again once a line ending in a newline was read;
#     `PL_write_prompt(true)` where it is set, else a flush), over `user_input` and `user_output` as buffers that share ONE position record, as
#     `initIO` makes them share `Sinput`'s (so a prompt text and the goal's text move the line position that `PrologPrompt` tests).
#   * A case is steps joined by `;;`; a step is `p1|p2|line|after`: the atom for prompt1/1 (`-`: not called), the atom for prompt/2 (`-`: not
#     called), the line delivered (ends in a newline), the text written after it was read. `\n` is a newline in every field.
#   * Every answer line is swipl's, PINNED (two runs byte-identical); no live comparison (a pty is the generator's).
#   * ONE extractor: `_tp_enc` encodes a transcript (the kernel's) and the pins are in the same encoding (the generator's `enc`).
using Test, LogicKernel
const LK = LogicKernel

# TERM TYPES PER CHUNK: REFERENCE — the prompt functions ride the term layer (atoms); every type in CI and at milestones
include(joinpath(@__DIR__, "..", "term_under_test.jl"))
const _TP = lk_term_type(Union{Int64, Float64, String})

const _TP_CASES = [
    ("tp01", raw"-|-|a\n|got\n"),
    ("tp02", raw"P1> |P2> |a\n|got(a)\n;;-|-|b\n|got(b)\n"),
    ("tp03", raw"-|P2> |a\n|got(a);;-|-|b\n|got(b)\n"),
    ("tp04", raw"-|P2> |a\n|;;-|-|b\n|;;-|-|c\n|x"),
    ("tp05", raw"-|P2> |a\n|got(a)\n;;P1b> |-|b\n|got(b)\n;;-|-|c\n|got(c)\n"),
    ("tp06", raw"-||a\n|got\n;;-|-|b\n|got(b)\n"),
    ("tp07", raw"||a\n|got\n;;-|P2> |b\n|got(b)\n"),
    ("tp08", raw"P1> |-|a\n|got\n;;P1> |-|b\n|got\n;;-|-|c\n|got\n"),
    ("tp09", raw"-|P2> |a\n|got(a);;P1m> |-|b\n|got(b)\n"),
    ("tp10", raw"-|P2> |a\n|got(a);;-|Q> |b\n|got(b)\n;;-|-|c\n|"),
    ("tp11", raw"-|A> |a\n|x\n;;-|B> |b\n|y\n;;-|-|c\n|z\n;;-|C> |d\n|"),
    ("tp12", raw"-|P2> |a\n|\n;;-|-|b\n|\n")
]

# the transcripts swipl 10.1.19 gives (filled by evidence/TOP1/gen_top1_rows.py): the case id, then its segments as character codes
const _TP_PINNED = [
    # PINS-BEGIN
    "tp01 124,58,32;103,111,116,10",
    "tp02 80,49,62,32;103,111,116,40,97,41,10,80,50,62,32;103,111,116,40,98,41,10",
    "tp03 80,50,62,32;103,111,116,40,97,41;103,111,116,40,98,41,10",
    "tp04 80,50,62,32;80,50,62,32;80,50,62,32;120",
    "tp05 80,50,62,32;103,111,116,40,97,41,10,80,49,98,62,32;103,111,116,40,98,41,10,80,50,62,32;103,111,116,40,99,41,10",
    "tp06 ;103,111,116,10;103,111,116,40,98,41,10",
    "tp07 ;103,111,116,10,80,50,62,32;103,111,116,40,98,41,10",
    "tp08 80,49,62,32;103,111,116,10,80,49,62,32;103,111,116,10,124,58,32;103,111,116,10",
    "tp09 80,50,62,32;103,111,116,40,97,41,80,49,109,62,32;103,111,116,40,98,41,10",
    "tp10 80,50,62,32;103,111,116,40,97,41;103,111,116,40,98,41,10,81,62,32;",
    "tp11 65,62,32;120,10,66,62,32;121,10,66,62,32;122,10,67,62,32;",
    "tp12 80,50,62,32;10,80,50,62,32;10"
# PINS-END
]

_tp_dec(f::AbstractString)::String = replace(f, "\\n" => "\n")
"The steps of a case: `(p1, p2, line, after)`, `p1`/`p2` nothing where the field is `-`."
function _tp_steps(spec::String)::Vector{NTuple{4, Union{Nothing, String}}}
    return [
        begin
            f = [_tp_dec(x) for x in split(st, "|"; keepempty=true)]
            @assert length(f) == 4
            (f[1] == "-" ? nothing : f[1], f[2] == "-" ? nothing : f[2], f[3], f[4])
        end for st in split(spec, ";;"; keepempty=true)
    ]
end

"A transcript as the generator's `enc` writes it: the segments as character codes, `;` between segments, `,` between codes."
_tp_enc(segs::Vector{String})::String =
    join([join(Int.(collect(s)), ",") for s in segs], ";")

"""
The kernel's transcript of `steps`: `Sread_user`'s three lines (pl-file.c:5992-6004) by hand over a `user_input` and a `user_output` made
of buffers that share one position record (`initIO`).
"""
function _tp_transcript(::Type{T}, steps)::Vector{String} where {T}
    gd = LK.PL_global_data{T}()
    ld = LK.PL_local_data{T}(gd)
    inb = IOBuffer()
    outb = IOBuffer()
    ui = LK.set_standard_stream!(ld, LK.SNO_USER_INPUT, inb)
    uo = LK.set_standard_stream!(ld, LK.SNO_USER_OUTPUT, outb)
    uo.position = ui.position                       # the standard streams share Sinput's position record (initIO)
    ld.prompt_next = true                           # ResetTty: LD->prompt.next = true
    prompts = String[]
    afters = String[]
    for (p1, p2, line, after) in steps
        p1 === nothing || LK.prompt1(ld, lk_sym(T, Symbol(p1)))
        p2 === nothing || (ld.prompt_current = lk_sym(T, Symbol(p2)))
        if ld.prompt_next
            LK.PL_write_prompt(gd, ld, true)        # Sread_user: PL_write_prompt(true)
        else
            LK.Sflush(uo)                           # else Sflush(Suser_output)
        end
        push!(prompts, String(take!(outb)))
        write(inb, line)                            # the terminal delivers the line
        for _ in 1:length(line)
            LK.Sgetcode(ui)
        end
        endswith(line, "\n") && (ld.prompt_next = true)   # buf[rc-1] == '\n'
        for c in after                              # the goal's own text
            LK.Sputcode(Int(c), uo)
        end
        LK.Sflush(uo)
        push!(afters, String(take!(outb)))
    end
    segs = String[prompts[1]]
    for i in eachindex(afters)
        push!(segs, afters[i] * (i < length(prompts) ? prompts[i + 1] : ""))
    end
    return segs
end

"The pin of case `id`: its segments' encoding."
function _tp_pin(id::String)::Union{Nothing, String}
    for l in _TP_PINNED
        k, v = split(l, " "; limit=2)
        k == id && return String(v)
    end
    return nothing
end

@testset "swipl-pinned prompts: the transcript of each case" begin
    kernel = String[]
    pins = String[]
    for (id, spec) in _TP_CASES
        steps = _tp_steps(spec)
        segs = _tp_transcript(_TP, steps)
        @test length(segs) == length(steps) + 1
        pin = _tp_pin(id)
        @test pin !== nothing
        pin === nothing && continue
        push!(kernel, _tp_enc(segs))
        push!(pins, pin)
        @test _tp_enc(segs) == pin
    end
    # not vacuous, both sides through ONE extractor: the cases are all pinned, prompts were written (some segments non-empty) and withheld
    # (some prompt positions empty), on the kernel's side as on swipl's
    @test length(pins) == length(_TP_CASES) == length(_TP_PINNED)
    @test [first(split(l, " ")) for l in _TP_PINNED] == first.(_TP_CASES)
    @test length(unique(pins)) > 6
    @test count(!isempty, kernel) == length(kernel) > 0
    nonempty_segments(ls) = sum(count(!isempty, split(l, ";"; keepempty=true)) for l in ls)
    empty_segments(ls) = sum(count(isempty, split(l, ";"; keepempty=true)) for l in ls)
    @test nonempty_segments(pins) > 20
    @test empty_segments(pins) > 3
    @test nonempty_segments(kernel) == nonempty_segments(pins)
    @test empty_segments(kernel) == empty_segments(pins)
end

@testset "the pins are swipl's own words (decoded)" begin
    # the default prompt, prompt1/1 once, prompt/2 at the line start, nothing mid-line: read from the decoded pins, not from the kernel
    dec(l) = [String(Char.(parse.(Int, filter(!isempty, split(s, ","))))) for s in split(split(l, " "; limit=2)[2], ";"; keepempty=true)]
    @test dec(_tp_pin("tp01"))[1] == "|: "
    @test dec(_tp_pin("tp02"))[1] == "P1> "
    @test dec(_tp_pin("tp02"))[2] == "got(a)\nP2> "
    @test dec(_tp_pin("tp03")) == ["P2> ", "got(a)", "got(b)\n"]
    @test dec(_tp_pin("tp09"))[2] == "got(a)P1m> "
end
